const PptxGenJS = require('pptxgenjs');

const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches

// Color palette
const COLORS = {
  primary: '2B579A',    // Deep blue
  secondary: '4472C4',  // Medium blue
  accent: 'ED7D31',     // Orange accent
  dark: '1F2937',       // Dark gray for body text
  light: 'F3F4F6',      // Light gray background
  white: 'FFFFFF',
};

const FONT = '微软雅黑';

// Helper: add a colored top bar to every slide
function addTopBar(slide) {
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 0, w: 13.33, h: 0.12,
    fill: { color: COLORS.primary },
  });
}

// Helper: add page number
function addPageNum(slide, num, total) {
  slide.addText(`${num} / ${total}`, {
    x: 11.8, y: 7.0, w: 1.2, h: 0.35,
    fontSize: 10, color: '9CA3AF', fontFace: FONT, align: 'right',
  });
}

// ===== Slide 1: Title =====
{
  const slide = pres.addSlide();
  slide.background = { fill: COLORS.primary };

  slide.addText('团队协作', {
    x: 1.0, y: 1.8, w: 11.33, h: 1.5,
    fontSize: 54, bold: true, color: COLORS.white, fontFace: FONT, align: 'center',
  });

  slide.addText('打造高效协同的团队文化', {
    x: 1.0, y: 3.5, w: 11.33, h: 0.8,
    fontSize: 24, color: 'D1E5FF', fontFace: FONT, align: 'center',
  });

  // Decorative line
  slide.addShape(pres.ShapeType.rect, {
    x: 5.0, y: 4.6, w: 3.33, h: 0.06,
    fill: { color: COLORS.accent },
  });

  slide.addText('2024 · 团队管理系列', {
    x: 1.0, y: 5.2, w: 11.33, h: 0.6,
    fontSize: 16, color: 'A8C8F0', fontFace: FONT, align: 'center',
  });
}

// ===== Slide 2: Why Teamwork Matters =====
{
  const slide = pres.addSlide();
  addTopBar(slide);
  addPageNum(slide, 2, 5);

  slide.addText('为什么团队协作至关重要？', {
    x: 0.8, y: 0.5, w: 11.73, h: 0.9,
    fontSize: 32, bold: true, color: COLORS.primary, fontFace: FONT,
  });

  const points = [
    { title: '提升效率', desc: '合理分工让每个人发挥所长，整体产出远超个人之和' },
    { title: '激发创新', desc: '多元视角碰撞产生新想法，避免思维盲区与决策偏差' },
    { title: '增强韧性', desc: '互相补位与支持使团队在压力下保持稳定交付能力' },
    { title: '促进成长', desc: '知识共享与反馈循环加速每位成员的技能提升' },
  ];

  points.forEach((p, i) => {
    const yPos = 1.8 + i * 1.3;
    // Accent dot
    slide.addShape(pres.ShapeType.ellipse, {
      x: 1.0, y: yPos + 0.15, w: 0.22, h: 0.22,
      fill: { color: COLORS.accent },
    });
    slide.addText(p.title, {
      x: 1.5, y: yPos - 0.05, w: 4.0, h: 0.5,
      fontSize: 22, bold: true, color: COLORS.dark, fontFace: FONT,
    });
    slide.addText(p.desc, {
      x: 1.5, y: yPos + 0.45, w: 10.0, h: 0.6,
      fontSize: 16, color: '4B5563', fontFace: FONT,
    });
  });
}

// ===== Slide 3: Core Principles =====
{
  const slide = pres.addSlide();
  addTopBar(slide);
  addPageNum(slide, 3, 5);

  slide.addText('高效协作的四大核心原则', {
    x: 0.8, y: 0.5, w: 11.73, h: 0.9,
    fontSize: 32, bold: true, color: COLORS.primary, fontFace: FONT,
  });

  const principles = [
    { title: '目标对齐', desc: '共同愿景与清晰 OKR\n确保力往一处使' },
    { title: '透明沟通', desc: '信息及时公开同步\n减少猜测与信息差' },
    { title: '信任授权', desc: '给予自主权与容错空间\n激发主人翁意识' },
    { title: '复盘迭代', desc: '定期回顾总结经验\n持续优化协作流程' },
  ];

  // 2x2 card layout
  principles.forEach((p, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const xBase = 0.8 + col * 6.0;
    const yBase = 1.8 + row * 2.6;

    // Card background
    slide.addShape(pres.ShapeType.roundRect, {
      x: xBase, y: yBase, w: 5.5, h: 2.2,
      fill: { color: COLORS.light },
      rectRadius: 0.15,
    });

    // Number badge
    slide.addShape(pres.ShapeType.ellipse, {
      x: xBase + 0.3, y: yBase + 0.3, w: 0.55, h: 0.55,
      fill: { color: COLORS.secondary },
    });
    slide.addText(`${i + 1}`, {
      x: xBase + 0.3, y: yBase + 0.3, w: 0.55, h: 0.55,
      fontSize: 20, bold: true, color: COLORS.white, fontFace: FONT, align: 'center', valign: 'middle',
    });

    slide.addText(p.title, {
      x: xBase + 1.1, y: yBase + 0.3, w: 4.0, h: 0.55,
      fontSize: 22, bold: true, color: COLORS.dark, fontFace: FONT, valign: 'middle',
    });

